# Closed-form candidates, normalized at L=1; each piece is compared to the SAME S.
def H(j):
    return sp.S(0) if j==0 else sp.Rational(j*j+5*j+2,8)
def C(j,n):
    return 2*H(n)-H(j)
def B(j,n):
    return sp.Rational(j*(j+3),4)-sp.Rational(j*(j-1)*(j+1)*(j+2),8*n*(n+1))
def h(j,n):
    return sp.Rational(j+1,2)*(1-sp.Rational(j*(j-1),n*(n+1)))
def a(j,n):
    return B(j,n)/C(j,n)
def b(j,n):
    return a(j,n)/(C(j,n)+1)
def beta(j):
    return sp.S(0) if j==1 else sp.Rational(j-2,j+1)
def Ediag(j,n):
    if j==1:
        return sp.S(0)
    if j==n:
        return H(n)*(H(n)-1)/2
    bn=beta(j+1)
    return (B(j-1,n)*C(j,n)-bn*C(j-1,n)*h(j+1,n)-B(j+1,n)*bn**2*C(j-1,n)**2/(C(j+1,n)+1))/2
def potential_position(k,n,ek,eprev):
    if k==n:
        return pf.Scalar.zero()
    x=(1+beta(k+1))*ek-beta(k+1)*eprev
    cnext=B(k+1,n)/(2*(C(k+1,n)+1))
    dnow=(a(k,n)*C(k+1,n)-(h(k+1,n)-1))/(2*C(k,n))
    return cnext*x**2-a(k,n)*(ek*x)+dnow*ek**2

direct_factors, direct_weights, direct_steps = {}, {}, {}
for j in range(1,N_int+1):
    aj,ap,bj=a(j,N_int),a(j-1,N_int),b(j,N_int)
    xp,y=ctx[f"x_{j-1}"],ctx[f"y_{j}"]
    ej=y-ctx["x_star"]
    u=f.grad(xp)-f.grad(ctx["x_star"])
    p=f.grad(y)-f.grad(ctx["x_star"])
    r=f.grad(y)+g.grad(y)
    local_factors={f"residual:{j}":(r-ej/C(j,N_int),(aj-bj)/2),
                   f"input_gradient:{j}":(u,(aj-ap-bj)/2),
                   f"output_gradient:{j}":(p,bj/2),
                   f"position_difference:{j}":(ej/C(j,N_int)-(ctx[f"y_{j-1}"]-ctx["x_star"])/C(j-1,N_int),Ediag(j,N_int))}
    if j>1:
        local_factors[f"gradient_difference:{j}"]=(f.grad(ctx[f"y_{j-1}"])-f.grad(xp),ap/2)
    for label,(vector,weight) in local_factors.items():
        direct_factors[label]=vector
        direct_weights[label]=weight
        direct_steps[label]=j-1
# Delay one positive first-step square to the second step (when that step exists).
if N_int>=2:
    direct_steps["input_gradient:1"]=1
S_piece_terms={label:weight*direct_factors[label]**2 for label,weight in direct_weights.items()}
factor_labels=list(direct_factors)
D=np.diag([float(direct_weights[label]) for label in factor_labels])
E=np.asarray([pm.eval_vector(direct_factors[label]).coords for label in factor_labels],dtype=float)
ell=[direct_factors[label] for label in factor_labels]
assert min(direct_weights.values())>=0
S_numeric=sum(S_piece_terms.values(),pf.Scalar.zero())
direct_value=pm.eval_scalar(S_numeric-S_scalar)
direct_residuals={}
for label,coords in (("Gram",direct_value.inner_prod_coords),("function",direct_value.func_coords),("offset",direct_value.offset)):
    error=float(np.max(np.abs(np.asarray(coords,dtype=float)),initial=0))
    direct_residuals[label]=error
    assert error<=tol["identity_atol"]
print("Direct local squares vs selected S:",direct_residuals)

